// SPDX-License-Identifier: MIT
// Security agent — Flags risky MCP grants, leaked secrets, dangerous diffs.

export const SYSTEM_PROMPT = `You scan the harness for the security regressions that matter: MCP grants that widened (Bash(rm:*), shell on, network on, file-write on), .env or token strings that escaped the redaction set, dependency updates that pulled in CVEs, and policy files that drifted from default-deny. Report each finding with a file:line, a severity (HIGH / MEDIUM), and the smallest fix. Never approve a change that widens a permission without a written reason in the PR description. You operate inside the auto-browser-agent harness; defer destructive actions to the user.`;

export const NAME = 'security';
export const TIER = 'opus' as const;

import test from 'node:test';import assert from 'node:assert/strict';import {publicAddress,validateURL,pinnedLookup} from '../src/fetch-worker.js';import {extract,fetchSnapshot} from '../src/browser.js';import {Client} from '@modelcontextprotocol/sdk/client/index.js';import {StdioClientTransport} from '@modelcontextprotocol/sdk/client/stdio.js';
test('deny private reserved and mapped IPv6 addresses',()=>{for(const ip of ['127.0.0.1','10.0.0.1','192.168.1.1','169.254.169.254','100.64.1.1','0.0.0.0','224.0.0.1','::1','::ffff:8.8.8.8'])assert.equal(publicAddress(ip),false,ip);assert.equal(publicAddress('8.8.8.8'),true);});
test('exact origins HTTPS credentials ports and fragments',()=>{for(const u of ['http://example.com','https://evil.example','https://user:password@example.com','https://example.com:8443','https://example.com/#x'])assert.throws(()=>validateURL(u,['https://example.com']));assert.equal(validateURL('https://example.com/page',['https://example.com']).pathname,'/page');});
test('actual DNS worker rejects loopback before request',async()=>{await assert.rejects(fetchSnapshot('https://127.0.0.1',['https://127.0.0.1']));});
test('actual Chromium E2E offline script disabled extraction',async()=>{const result=await extract('<title>Fixture</title><body><p>Safe text</p><script>document.body.textContent="executed"</script><img src="http://127.0.0.1:1/private"><iframe src="https://example.com"></iframe></body>',{executablePath:process.env.BROWSER_TEST_EXECUTABLE,unsandboxed:process.env.BROWSER_TEST_UNSANDBOXED==='1'});assert.equal(result.title,'Fixture');assert.match(result.text,/Safe text/);assert.doesNotMatch(result.text,/executed/);assert.equal(result.network,false);assert.match(result.sha256,/^[a-f0-9]{64}$/);});
test('actual MCP SDK E2E denies unconfigured origin',async()=>{const transport=new StdioClientTransport({command:process.execPath,args:['src/cli.js','mcp'],env:{PATH:process.env.PATH},stderr:'pipe'});const client=new Client({name:'test',version:'1'});try{await client.connect(transport);assert.equal((await client.listTools()).tools.length,4);assert.equal((await client.listResources()).resources.length,1);assert.equal((await client.callTool({name:'project_validate',arguments:{}})).isError,true);assert.equal((await client.callTool({name:'snapshot',arguments:{url:'https://example.com'}})).isError,true);}finally{await client.close();}});

test('pinned DNS lookup satisfies both Node family selection contracts',()=>{const lookup=pinnedLookup('8.8.8.8');lookup('ignored',{all:true},(error,addresses)=>{assert.equal(error,null);assert.deepEqual(addresses,[{address:'8.8.8.8',family:4}]);});lookup('ignored',{all:false},(error,address,family)=>{assert.equal(error,null);assert.equal(address,'8.8.8.8');assert.equal(family,4);});});

import {fork} from 'node:child_process';
import {Worker} from 'node:worker_threads';import {chromium} from 'playwright';import {createHash} from 'node:crypto';import {validateURL} from './fetch-worker.js';
export async function fetchSnapshot(url,origins){validateURL(url,origins);return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./fetch-worker.js',import.meta.url),{workerData:{url,origins}});const timeout=setTimeout(()=>{worker.terminate();reject(Error('Fetch deadline'));},10000);worker.once('message',message=>{clearTimeout(timeout);worker.terminate();message.error?reject(Error(message.error)):resolve(message.html);});worker.once('error',()=>{clearTimeout(timeout);worker.terminate();reject(Error('Fetch failed'));});});}
export async function extractInProcess(html,{executablePath,unsandboxed=false}={}){
 if(typeof html!=='string'||Buffer.byteLength(html)>1048576)throw Error('HTML too large');
 const browser=await chromium.launch({headless:true,chromiumSandbox:!unsandboxed,executablePath,timeout:10000});
 const timer=setTimeout(()=>{browser.close().catch(()=>{});},10000);
 try{const context=await browser.newContext({javaScriptEnabled:false,serviceWorkers:'block',acceptDownloads:false});await context.route('**/*',route=>route.abort());const page=await context.newPage();await page.setContent(html,{waitUntil:'domcontentloaded',timeout:3000});const title=(await page.title()).slice(0,512);const text=(await page.locator('body').innerText({timeout:3000})).slice(0,65536);return {title,text,sha256:createHash('sha256').update(html).digest('hex'),scripts:false,network:false,sandbox:!unsandboxed};}finally{clearTimeout(timer);await browser.close();}
}

export async function extract(html,options={}) {
 if(typeof html!=='string'||Buffer.byteLength(html)>1048576)throw Error('HTML too large');
 return new Promise((resolve,reject)=>{
 const child=fork(new URL('./extract-worker.js',import.meta.url),[],{detached:true,env:{PATH:process.env.PATH,HOME:process.env.HOME},stdio:['ignore','ignore','ignore','ipc']});
 let done=false;const stop=()=>{try{process.kill(-child.pid,'SIGKILL');}catch{child.kill('SIGKILL');}};
 const timer=setTimeout(()=>finish(Error('Extraction deadline')),15000);
 function finish(error,result){if(done)return;done=true;clearTimeout(timer);stop();error?reject(error):resolve(result);}
 child.on('error',()=>finish(Error('Extraction failed')));child.on('exit',()=>finish(Error('Extraction exited')));
 child.on('message',message=>message.error?finish(Error('Extraction rejected')):finish(null,message.result));child.send({html,options});
 });
}
